bash -lc cat > /mnt/data/audit_transcripts.py <<'PY'
import json,glob,os,re,collections,hashlib
all_data={}
for fn in glob.glob('/mnt/data/chatgpt-*.json'):
 d=json.load(open(fn)); all_data[d['conversationId']]=d

def show(pattern,roles=('user','assistant'),limit=80,case=False,clip=650,threads=None):
 rx=re.compile(pattern,0 if case else re.I)
 rows=[]
 for d in all_data.values():
  if threads and not any(y.lower() in d['title'].lower() for y in threads):continue
  for m in d['messages']:
   if m['role'] not in roles:continue
   found=rx.search(m.get('text',''))
   if found:
    start=max(found.start()-180,0);end=found.end()+400
    excerpt=m['text'][start:end].replace('\n',' ')
    rows.append((d['title'],m['index'],m['role'],excerpt[:clip]))
 print('MATCHES',len(rows),'PATTERN',pattern)
 for title,index,role,excerpt in rows[:limit]:print(f'[{title} #{index} {role}] {excerpt}')

if __name__=='__main__':
 import sys
 show(sys.argv[1],limit=int(sys.argv[2]) if len(sys.argv)>2 else 80)
