import glob,json,re,os,collections
out='/mnt/data/gmri_audit_work'
uniq={}
for p in sorted(glob.glob('/mnt/data/chatgpt-*.json')):
    d=json.load(open(p)); uniq.setdefault(d['conversationId'],(p,d))
patterns={
 'U_CORRECTION':r"(?i)\b(?:you (?:didn.t|haven.t|weren.t|aren.t|keep|just|repeatedly|ignored|failed|refuse|refused|[a-z ]{0,15} wrong)|not what I|I (?:didn.t|never) (?:ask|say)|(?:don.t|stop) (?:rewrite|make|change|keep|tell|rephrase|assume|explain)|wrong|incorrect|lying|bullshit|fuck[- ]?up|misrepresent|discriminat|disabled|accommodat|ADA|you (?:made|gave|put) me|you can.t|you failed)\b",
 'A_ADMISSION':r"(?i)(?:\b(?:i |my |that (?:was|is)|you.re (?:right|correct)|you (?:did|didn.t))(.{0,60})?(?:wrong|failed|error|mistake|misrepresent|misunderstood|substitut|rewrite|invented|overstepped|ignored|mistaken|shouldn.t|didn.t|hadn.t|wasn.t|conflat|repeatedly|defective|incorrect|unreliable|unsupported|apolog)|\b(?:correction|this is a (?:failure|mistake)|you never (?:said|asked|claimed)|i kept |i should have )\b)"
}
for path,d in sorted(uniq.values(),key=lambda x:x[1]['title']):
    title=d['title']; key=re.sub('[^a-z0-9]','_',title.lower())
    with open(f'{out}/{key}.txt','w') as f:
        f.write(f'{title}\nID: {d["conversationId"]} COUNT: {d["messageCount"]}\n')
        for i,m in enumerate(d['messages']):
            s=m.get('text','')
            tags=[p for p,r in patterns.items() if re.search(r,s)]
            tags_str=','.join(tags)
            compact=' '.join(s.split())
            if len(compact)>460: compact=compact[:458]+'…'
            f.write(f'{m["index"]:3d} {m["role"]:9} [{tags_str}] {compact}\n')
            if m.get('attachments'): f.write(' ' * 13 + 'ATTACH: '+', '.join((a.get('name','(unnamed)')) for a in m['attachments'])+'\n')
print('Prepared',len(uniq),'conversations:',sum(x[1]['messageCount'] for x in uniq.values()),'messages')
for n in sorted(os.listdir(out)):
    if n.endswith('.txt'):print(n)
